"""CSV export of the team assignments for the events team."""
import csv
import io

from .teams import assign_teams


def teams_csv(names: list[str], team_count: int) -> str:
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\n")
    w.writerow(["team", "member"])
    for i, team in enumerate(assign_teams(names, team_count), start=1):
        for member in team:
            w.writerow([f"Team {i}", member])
    return buf.getvalue()
"""Splits sign-ups into teams for the company hackathon."""


def clean_names(names: list[str]) -> list[str]:
    """Trimmed, de-duplicated names (case-insensitive), keeping the first spelling seen."""
    seen: dict[str, str] = {}
    for n in names:
        n = n.strip()
        if n and n.lower() not in seen:
            seen[n.lower()] = n
    return list(set(seen.values()))


def assign_teams(names: list[str], team_count: int) -> list[list[str]]:
    """Deal the cleaned names into `team_count` teams round-robin, in alphabetical
    (case-insensitive) order: the 1st name goes to team 0, the 2nd to team 1, and so on.
    The result is fully deterministic: the same sign-ups always give the same teams.
    """
    if team_count <= 0:
        raise ValueError("team_count must be positive")
    teams: list[list[str]] = [[] for _ in range(team_count)]
    for i, name in enumerate(clean_names(names)):
        teams[i % team_count].append(name)
    return teams
from roster.export import teams_csv


def test_csv_shape():
    out = teams_csv(["a", "b", "c"], 2).splitlines()
    assert out[0] == "team,member"
    assert len(out) == 4
    assert all(line.startswith("Team ") for line in out[1:])


def test_csv_is_stable():
    names = ["Zed", "amy", "Kai", "bo", "Lu", "eve", "Ray"]
    assert teams_csv(names, 3) == (
        "team,member\n"
        "Team 1,amy\nTeam 1,Kai\nTeam 1,Zed\n"
        "Team 2,bo\nTeam 2,Lu\n"
        "Team 3,eve\nTeam 3,Ray\n"
    )
